// Circleback on the person's own API key: every operation of Circleback's public API (meetings, notes, transcripts,
// action items, calendar, people, companies, folders, tags). actions.json is generated by
// `bun scripts/openapi-actions.ts circleback`. Circleback's webhooks are set up only in its own Automations page,
// so new meetings and action items start automations by polling (polls/circleback.ts). COVERAGE.md says what's where.
import { AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { type Api, type Send, call, specActions } from "../openapi";

export const api: Api = { name: "Circleback", base: "https://circleback.ai/api", tokenHelp: "circleback.ai → Settings → API keys" };

const ACTIONS = new URL("./actions.json", import.meta.url);
const generated = await specActions(ACTIONS, api);
const sends: Record<string, Send> = Object.fromEntries(
  ((await Bun.file(ACTIONS).json()) as { actions: { name: string; send: Send }[] }).actions.map((a) => [a.name, a.send]),
);

// Lists answer a bare array and put the next page in a Link header (rel="next"), which call() doesn't read; these hand
// back {items, next_cursor} so the next page can be asked for.
async function paged(send: Send, input: Record<string, unknown>, key: string) {
  const q = new URLSearchParams();
  for (const k of send.query) for (const v of [input[k]].flat()) if (v !== undefined) q.append(k, String(v));
  const res = await fetch(`${api.base}${send.path}${q.size ? `?${q}` : ""}`, { headers: { Authorization: `Bearer ${key}` } });
  const text = await res.text();
  let body: any;
  try {
    body = JSON.parse(text);
  } catch {
    body = text;
  }
  if (res.status === 401) throw new AppsError(`Circleback rejected the API key; make a new one (${api.tokenHelp}) and reconnect`, true, body?.error ?? text);
  if (!res.ok) throw new AppsError(`Circleback: ${body?.error ?? (text || res.statusText)} (${res.status})`);
  const next = res.headers.get("link")?.match(/<([^>]+)>\s*;\s*rel="?next"?/)?.[1];
  return { items: body, next_cursor: next ? (new URL(next, api.base).searchParams.get("cursor") ?? undefined) : undefined };
}

const withPages = (name: string, a: OwnAction): OwnAction =>
  sends[name]?.query.includes("cursor")
    ? {
        ...a,
        description: `${a.description} Answers {items, next_cursor}; pass next_cursor as cursor for the next page.`,
        run: (i: Record<string, unknown>, key: string) => paged(sends[name]!, i, key),
      }
    : a;

export const circleback: OwnApp = {
  app: "circleback",
  name: "Circleback",
  logo: "/logos/circleback.png",
  keyField: {
    label: "API key",
    help: "In Circleback, open Settings → API keys (circleback.ai/settings?tab=api-access), create a key and copy it; it's shown only once. Every plan, Free included, has API access. Emplio sees and changes what your own Circleback login can: your meetings and the ones shared with you.",
    placeholder: "cb_...",
  },
  async check(key) {
    const me = (await call(api, key, sends.get_current_account!, {})) as { email?: string };
    return me.email || "Circleback";
  },
  actions: Object.fromEntries(Object.entries(generated).map(([n, a]) => [n, withPages(n, a)])),
};
